CREATE SCHEMASTORE VIEW police_area_v WITH CONTAINER housecheck AS SELECT 'GU2 7XH' AS postcode, force AS police_force, neighbourhood FROM housecheck_live.hood_gu27xh UNION ALL SELECT 'SO14 5FN' AS postcode, force AS police_force, neighbourhood FROM housecheck_live.hood_so145fn UNION ALL SELECT 'BL4 0LL' AS postcode, force AS police_force, neighbourhood FROM housecheck_live.hood_bl40ll
