CREATE SCHEMASTORE VIEW street_crime_v WITH CONTAINER housecheck AS SELECT concat(CAST(id AS STRING), '-gu27xh') AS crime_key, 'GU2 7XH' AS postcode, category AS crime_category, month AS crime_month, location.street.name AS street_name, outcome_status.category AS outcome FROM housecheck_live.crime_gu27xh UNION ALL SELECT concat(CAST(id AS STRING), '-so145fn') AS crime_key, 'SO14 5FN' AS postcode, category AS crime_category, month AS crime_month, location.street.name AS street_name, outcome_status.category AS outcome FROM housecheck_live.crime_so145fn UNION ALL SELECT concat(CAST(id AS STRING), '-bl40ll') AS crime_key, 'BL4 0LL' AS postcode, category AS crime_category, month AS crime_month, location.street.name AS street_name, outcome_status.category AS outcome FROM housecheck_live.crime_bl40ll
-- @@stmt
CREATE SCHEMASTORE VIEW fsa_establishment_v WITH CONTAINER housecheck AS SELECT concat(CAST(e.FHRSID AS STRING), '-gu27xh') AS food_key, 'GU2 7XH' AS postcode, CAST(e.FHRSID AS STRING) AS fhrsid, e.BusinessName AS business_name, e.BusinessType AS business_type, CAST(e.RatingValue AS STRING) AS rating_value, substr(CAST(e.RatingDate AS STRING), 1, 10) AS rating_date, e.LocalAuthorityName AS local_authority FROM housecheck_live.fsa_gu27xh LATERAL VIEW explode(establishments) AS e UNION ALL SELECT concat(CAST(e.FHRSID AS STRING), '-so145fn') AS food_key, 'SO14 5FN' AS postcode, CAST(e.FHRSID AS STRING) AS fhrsid, e.BusinessName AS business_name, e.BusinessType AS business_type, CAST(e.RatingValue AS STRING) AS rating_value, substr(CAST(e.RatingDate AS STRING), 1, 10) AS rating_date, e.LocalAuthorityName AS local_authority FROM housecheck_live.fsa_so145fn LATERAL VIEW explode(establishments) AS e UNION ALL SELECT concat(CAST(e.FHRSID AS STRING), '-bl40ll') AS food_key, 'BL4 0LL' AS postcode, CAST(e.FHRSID AS STRING) AS fhrsid, e.BusinessName AS business_name, e.BusinessType AS business_type, CAST(e.RatingValue AS STRING) AS rating_value, substr(CAST(e.RatingDate AS STRING), 1, 10) AS rating_date, e.LocalAuthorityName AS local_authority FROM housecheck_live.fsa_bl40ll LATERAL VIEW explode(establishments) AS e
